                   : A[Id,,M] }}
  | wf_pi : forall (Γ : ctx) (i : nat) (A B : typ),
            {{ Γ ⊢ A : Type@i }} ->
            {{ Γ, A ⊢ B : Type@i }} -> {{ Γ ⊢ Π A B : Type@i }}
  | wf_fn : forall (Γ : ctx) (i : nat) (A B M : typ),
            {{ Γ ⊢ A : Type@i }} ->
            {{ Γ, A ⊢ M : B }} -> {{ Γ ⊢ λ A M : Π A B }}
  | wf_app : forall (Γ : ctx) (i : nat) (A B M N : typ),
             {{ Γ ⊢ A : Type@i }} ->
             {{ Γ, A ⊢ B : Type@i }} ->
